use App\Rules\PakistanPhone;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class ExamReports {
 public function __construct(public ExamAccess $exam,private SchoolAssessments $assessments){}
 public function cycle(Request $r,int $id,int $section):array{[$sid]=$this->exam->context($r);$s=$this->exam->section($r,$section);abort_unless($this->exam->classReports($r,$s),403,'Class-teacher or coordinator access is required for consolidated cards.');$c=DB::table('exam_cycles')->where('school_id',$sid)->where('id',$id)->where('academic_session_id',$s->academic_session_id)->first()??abort(404);$tests=DB::table('tests as t')->join('subjects as u','u.id','=','t.subject_id')->leftJoin('exam_papers as p','p.test_id','=','t.id')->where('t.school_id',$sid)->where('t.exam_cycle_id',$id)->where('t.section_id',$section)->orderBy('t.subject_id')->orderBy('t.test_date')->orderBy('t.id')->get(['t.*','u.name as subject_name','p.starts_at','p.ends_at','p.room']);$weights=DB::table('assessment_weightages')->where('school_id',$sid)->where('exam_cycle_id',$id)->where('class_id',$s->class_id)->orderBy('subject_id')->orderBy('assessment_type')->get();$reports=DB::table('consolidated_result_snapshots as p')->join('enrollments as e','e.id','=','p.enrollment_id')->join('students as u','u.id','=','e.student_id')->where('p.school_id',$sid)->where('p.exam_cycle_id',$id)->where('e.section_id',$section)->orderByDesc('p.revision')->get(['p.id','p.revision','p.enrollment_id','p.published_at','p.payload','u.first_name','u.last_name','u.admission_no']);$shareCounts=DB::table('report_shares')->where('school_id',$sid)->whereIn('consolidated_snapshot_id',$reports->pluck('id'))->selectRaw('consolidated_snapshot_id,COUNT(DISTINCT guardian_id) as n')->groupBy('consolidated_snapshot_id')->pluck('n','consolidated_snapshot_id');$latest=$reports->unique('enrollment_id')->keyBy('enrollment_id');foreach($reports as $report){$p=json_decode($report->payload,true);$report->shared_count=(int)($shareCounts[$report->id]??0);$report->percent=$p['percent']??null;$report->grade=$p['grade']??'—';$report->outcome=$p['outcome']??'Legacy';$report->rank=$p['rank']??null;$report->is_current=$latest[$report->enrollment_id]->id===$report->id&&($p['source_digest']??null)===$this->digest($tests,$weights);unset($report->payload);}$candidates=DB::table('exam_candidates as x')->join('enrollments as e','e.id','=','x.enrollment_id')->join('students as u','u.id','=','e.student_id')->where('x.school_id',$sid)->where('x.exam_cycle_id',$id)->where('e.section_id',$section)->orderBy('x.roll_no')->get(['x.enrollment_id','x.roll_no','u.first_name','u.last_name','u.admission_no']);return ['school'=>DB::table('schools')->where('id',$sid)->first(['name','code']),'cycle'=>$c,'candidates'=>$candidates,'section'=>$s,'tests'=>$tests,'weights'=>$weights,'reports'=>$reports,'source_digest'=>$this->digest($tests,$weights),'can_publish'=>$this->exam->can($r,'tests.publish')&&$s->session_status==='active'&&$s->campus_status==='active'];}
 public function candidates(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);abort_unless($this->exam->can($r,'tests.publish'),403);$data=$this->cycle($r,$d['exam_cycle_id'],$d['section_id']);$this->exam->active($data['section']);$rows=collect();foreach($data['tests'] as $t)$rows=$rows->concat($this->exam->roster($sid,$data['section']->id,$t->test_date))->unique('enrollment_id')->values();if(!$rows->count()||$rows->pluck('student_id')->unique()->count()!==$rows->count())$this->exam->fail('Create exam papers and review candidate enrollment history first.');foreach($rows as $row)DB::table('exam_candidates')->insertOrIgnore(['school_id'=>$sid,'exam_cycle_id'=>$d['exam_cycle_id'],'enrollment_id'=>$row->enrollment_id,'roll_no'=>'E'.$row->enrollment_id,'created_at'=>now(),'updated_at'=>now()]);$this->exam->access->audit($r,'exams.candidates_registered','exam_cycles',$d['exam_cycle_id'],['section_id'=>$d['section_id'],'count'=>$rows->count()]);return ['message'=>'Exam candidates registered.'];});}
 private function digest($tests,$weights):string{return hash('sha256',json_encode(['tests'=>$tests->map(fn($t)=>[$t->id,$t->publication_revision,$t->status,$t->lock_version])->values()->all(),'weights'=>$weights->map(fn($w)=>[$w->subject_id,$w->assessment_type,$w->weight])->values()->all()]));}
 public function consolidate(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);abort_unless($this->exam->can($r,'tests.publish'),403);$data=$this->cycle($r,$d['exam_cycle_id'],$d['section_id']);$c=$data['cycle'];$s=$data['section'];$this->exam->active($s);if($c->lock_version!=$d['lock_version']||$data['source_digest']!==$d['source_digest'])$this->exam->fail('Exam papers, marks or setup changed. Reload the cycle before publishing cards.');if($c->ends_on>now('Asia/Karachi')->toDateString())$this->exam->fail('Consolidated cards can be published after the exam cycle ends.');$existing=$data['reports']->isNotEmpty();$reason=trim($d['reason']??'');if($existing&&mb_strlen($reason)<5)$this->exam->fail('A consolidated correction requires a reason of at least five characters.');$tests=$data['tests'];if(!$tests->count()||$tests->contains(fn($t)=>$t->status!=='published'||!$t->publication_revision))$this->exam->fail('Every paper in this section/cycle must have published results.');$g=$this->exam->scheme($sid,$c->grading_scheme_id);$subjects=DB::table('section_subjects as o')->join('subjects as u','u.id','=','o.subject_id')->where('o.school_id',$sid)->where('o.section_id',$s->id)->orderBy('u.name')->get(['u.id','u.name']);if(!$subjects->count())$this->exam->fail('Offer subjects before publishing exam cards.');$roster=collect();$byTest=[];
  foreach($tests as $t){$eligible=$this->exam->roster($sid,$s->id,$t->test_date);$results=DB::table('test_results')->where('school_id',$sid)->where('test_id',$t->id)->get();if($eligible->pluck('enrollment_id')->sort()->values()->all()!==$results->pluck('enrollment_id')->sort()->values()->all())$this->exam->fail('A paper roster changed after publication. Review enrollment history before consolidating.');$snapshots=DB::table('report_snapshots')->where('school_id',$sid)->whereIn('test_result_id',$results->pluck('id'))->where('revision',$t->publication_revision)->get()->keyBy('test_result_id');foreach($results as $result){$snapshot=$snapshots->get($result->id);if(!$snapshot)$this->exam->fail('One or more papers lack immutable published student reports.');$byTest[$t->id][$result->enrollment_id]=json_decode($snapshot->payload,true);}$roster=$roster->concat($eligible)->unique('enrollment_id')->values();}
  if(!$roster->count()||$roster->pluck('student_id')->unique()->count()!==$roster->count())$this->exam->fail('Exam candidate enrollment history needs review.');$config=[];foreach($subjects as $subject){$weights=$data['weights']->where('subject_id',$subject->id);if(!$weights->count())$weights=collect([(object)['assessment_type'=>'exam','weight'=>'100.00']]);if($weights->sum(fn($w)=>$this->exam->cents($w->weight))!==10000)$this->exam->fail('Subject weightages must total 100%.');foreach($weights as $w)if($this->exam->cents($w->weight)>0&&!$tests->contains(fn($t)=>$t->subject_id===$subject->id&&$t->assessment_type===$w->assessment_type))$this->exam->fail('Missing published '.$w->assessment_type.' paper for '.$subject->name.'.');$config[$subject->id]=$weights;}
  $school=DB::table('schools')->where('id',$sid)->first();$revision=$c->result_revision+1;$payloads=[];$scores=[];foreach($roster as $student){$lines=[];$totalEarned=0;$totalMax=0;$subjectScores=[];$allPass=true;foreach($subjects as $subject){$weighted=0.0;$activeWeight=0;$hasAbsent=false;$details=[];foreach($config[$subject->id] as $w){$weight=$this->exam->cents($w->weight);if(!$weight)continue;$earned=0;$maximum=0;foreach($tests->where('subject_id',$subject->id)->where('assessment_type',$w->assessment_type) as $t){$p=$byTest[$t->id][$student->enrollment_id]??null;if(!$p)continue;$details[]=['title'=>$p['title'],'status'=>$p['status'],'marks'=>$p['marks'],'max_marks'=>$p['max_marks'],'type'=>$w->assessment_type,'weight'=>$w->weight];if($p['status']==='exempt')continue;$hasAbsent=$hasAbsent||$p['status']==='absent';$earned+=$p['status']==='present'?$this->exam->cents($p['marks']):0;$maximum+=$this->exam->cents($p['max_marks']);}if($maximum){$weighted+=($earned/$maximum)*$weight;$activeWeight+=$weight;$totalEarned+=$earned;$totalMax+=$maximum;}}
   $bp=$activeWeight?(int)round($weighted*10000/$activeWeight,0,PHP_ROUND_HALF_UP):null;if($bp!==null&&$g->rounding_policy==='whole_percent')$bp=intdiv($bp+50,100)*100;$passed=$bp===null||$bp>=$this->exam->cents($g->rules['passing_percent']);if($bp!==null)$subjectScores[]=$bp;$allPass=$allPass&&$passed;$lines[]=['subject_id'=>$subject->id,'subject_name'=>$subject->name,'percent'=>$bp===null?null:$this->exam->number($bp),'grade'=>$bp===null?'—':$this->exam->grade($bp,$g),'outcome'=>$bp===null?'Exempt':($passed?'Pass':'Fail'),'has_absence'=>$hasAbsent,'components'=>$details];}
   $overall=$subjectScores?(int)round(array_sum($subjectScores)/count($subjectScores),0,PHP_ROUND_HALF_UP):null;if($overall!==null&&$g->rounding_policy==='whole_percent')$overall=intdiv($overall+50,100)*100;$outcome=$overall===null?'Exempt':($allPass?'Pass':'Fail');if($outcome==='Pass')$scores[$student->enrollment_id]=$overall;$payloads[$student->enrollment_id]=['kind'=>'cycle','school_name'=>$school->name,'school_code'=>$school->code,'student'=>(array)$student,'section_label'=>$s->class_name.' · '.$s->name.' · '.$s->campus_name.' · '.$s->session_name,'title'=>$c->name,'date'=>$c->ends_on,'subjects'=>$lines,'marks'=>$this->exam->number($totalEarned),'max_marks'=>$this->exam->number($totalMax),'percent'=>$overall===null?null:$this->exam->number($overall),'grade'=>$overall===null?'—':$this->exam->grade($overall,$g),'outcome'=>$outcome,'revision'=>$revision,'source_digest'=>$data['source_digest'],'correction_reason'=>$reason?:null,'grading'=>['name'=>$g->name,'version'=>$g->version,'rounding'=>$g->rounding_policy,'ties'=>$g->tie_policy,'passing_percent'=>$g->rules['passing_percent']],'policy'=>'Assessment groups aggregate marks/max, then apply configured weights. Exempt/not-enrolled groups are excluded and remaining weights renormalized. Subjects contribute equally to overall %. Every non-exempt subject must pass. Only passing candidates receive positions.'];
   DB::table('exam_candidates')->insertOrIgnore(['school_id'=>$sid,'exam_cycle_id'=>$c->id,'enrollment_id'=>$student->enrollment_id,'roll_no'=>'E'.$student->enrollment_id,'created_at'=>now(),'updated_at'=>now()]);}
  $ranks=$this->assessments->ranks($scores,$g->tie_policy);foreach($payloads as $enrollment=>$payload){$payload['rank']=$ranks[$enrollment]??null;DB::table('consolidated_result_snapshots')->insert(['school_id'=>$sid,'exam_cycle_id'=>$c->id,'enrollment_id'=>$enrollment,'revision'=>$revision,'grading_scheme_id'=>$g->id,'payload'=>json_encode($payload,JSON_UNESCAPED_UNICODE),'published_by'=>$this->exam->access->membership($r)->id,'published_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);}DB::table('exam_cycles')->where('school_id',$sid)->where('id',$c->id)->update(['lock_version'=>$c->lock_version+1,'result_revision'=>$revision,'updated_at'=>now()]);$this->exam->access->audit($r,'exams.cards_published','exam_cycles',$c->id,['section_id'=>$s->id,'revision'=>$revision,'reason'=>$reason?:null,'candidate_count'=>$roster->count(),'source_digest'=>$data['source_digest']]);return ['message'=>'Consolidated exam cards published.','revision'=>$revision];});}
 public function report(Request $r,string $kind,int $id):array{[$sid]=$this->exam->context($r);$table=$kind==='test'?'report_snapshots':'consolidated_result_snapshots';$snapshot=DB::table($table)->where('school_id',$sid)->where('id',$id)->first()??abort(404);$payload=json_decode($snapshot->payload,true);if(!isset($payload['student']['enrollment_id'],$payload['kind']))$this->exam->fail('Legacy report snapshot needs review before preview/sharing.');$enrollment=DB::table('enrollments')->where('school_id',$sid)->where('id',$payload['student']['enrollment_id'])->first()??abort(404);$s=$this->exam->section($r,$enrollment->section_id);
  if($kind==='test'){$result=DB::table('test_results')->where('school_id',$sid)->where('id',$snapshot->test_result_id)->first()??abort(404);[$test]=$this->exam->test($r,$result->test_id);$current=$test->status==='published'&&$test->publication_revision===$snapshot->revision;$field='report_snapshot_id';}
  else {abort_unless($this->exam->classReports($r,$s),403);$data=$this->cycle($r,$snapshot->exam_cycle_id,$s->id);$latest=DB::table('consolidated_result_snapshots')->where('school_id',$sid)->where('exam_cycle_id',$snapshot->exam_cycle_id)->where('enrollment_id',$snapshot->enrollment_id)->max('revision');$current=$latest===$snapshot->revision&&($payload['source_digest']??null)===$data['source_digest']&&!$data['tests']->contains(fn($t)=>$t->status!=='published');$field='consolidated_snapshot_id';}
  $canShare=$current&&$this->exam->sharing($r);$guardians=collect();if($canShare)$guardians=DB::table('student_guardians as l')->join('guardians as g','g.id','=','l.guardian_id')->where('l.school_id',$sid)->where('l.student_id',$enrollment->student_id)->where('l.can_receive_reports',true)->orderByDesc('l.is_primary')->orderBy('g.id')->get(['g.id','g.name','g.phone','g.whatsapp_phone','l.relationship','l.is_primary'])->map(function($g){$phone=PakistanPhone::canonical($g->whatsapp_phone?:$g->phone);$g->recipient_phone=preg_match('/^\+923[0-9]{9}$/D',$phone)?$phone:null;unset($g->phone,$g->whatsapp_phone);return $g;});$shares=DB::table('report_shares as x')->join('school_memberships as m','m.id','=','x.confirmed_by')->join('users as u','u.id','=','m.user_id')->join('guardians as g','g.id','=','x.guardian_id')->where('x.school_id',$sid)->where('x.'.$field,$id)->orderByDesc('x.id')->get(['x.id','x.guardian_id','x.recipient_phone','x.confirmed_at','x.resend_reason','u.name as confirmed_by_name','g.name as guardian_name']);if(!$this->exam->sharing($r))foreach($shares as $share)$share->recipient_phone='***'.substr($share->recipient_phone,-4);return ['id'=>$id,'kind'=>$kind,'payload'=>$payload,'published_at'=>$snapshot->published_at,'is_current'=>$current,'can_share'=>$canShare,'guardians'=>$guardians,'shares'=>$shares,'text'=>$this->text($payload)];}
 public function text(array $p):string{$student=$p['student'];$lines=[$p['school_name'],$p['title'].' · Revision '.$p['revision'],$student['first_name'].' '.($student['last_name']??'').' · '.$student['admission_no'],$p['section_label'],'Date: '.$p['date']];if($p['kind']==='test')$lines[]=$p['subject_name'].': '.($p['status']==='present'?$p['marks'].' / '.$p['max_marks']:ucfirst($p['status']));else foreach($p['subjects'] as $s)$lines[]=$s['subject_name'].': '.($s['percent']===null?'Exempt':$s['percent'].'% · '.$s['grade'].' · '.$s['outcome']);$lines[]='Result: '.$p['outcome'].' · '.($p['percent']===null?'—':$p['percent'].'%').' · Grade '.$p['grade'];if($p['rank'])$lines[]='Position: '.$p['rank'];if(!empty($p['remarks']))$lines[]='Remarks: '.$p['remarks'];return implode("\n",$lines);}
 public function share(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->exam->lock($r);$report=$this->report($r,$d['kind'],$d['id']);abort_unless($report['can_share'],403,'Only the current published report can be shared with permitted guardians.');$guardian=$report['guardians']->firstWhere('id',$d['guardian_id'])??abort(404);if(!$guardian->recipient_phone||$guardian->recipient_phone!==$d['recipient_phone'])$this->exam->fail('The registered guardian number changed or is not a valid mobile. Reload and verify the recipient before sending/confirming.');$field=$d['kind']==='test'?'report_snapshot_id':'consolidated_snapshot_id';$existing=DB::table('report_shares')->where('school_id',$sid)->where($field,$d['id'])->where('guardian_id',$guardian->id)->where('recipient_phone',$guardian->recipient_phone)->exists();$reason=trim($d['resend_reason']??'');if($existing&&$reason==='')return ['message'=>'This report revision is already confirmed shared with this guardian.'];if($existing&&mb_strlen($reason)<5)$this->exam->fail('A repeat sharing record needs a resend reason of at least five characters.');$id=DB::table('report_shares')->insertGetId(['school_id'=>$sid,$field=>$d['id'],'guardian_id'=>$guardian->id,'confirmed_by'=>$this->exam->access->membership($r)->id,'confirmed_at'=>now(),'channel'=>'whatsapp_manual','recipient_phone'=>$guardian->recipient_phone,'resend_reason'=>$reason?:null,'created_at'=>now(),'updated_at'=>now()]);$this->exam->access->audit($r,'exams.report_share_confirmed','report_shares',$id,['kind'=>$d['kind'],'snapshot_id'=>$d['id'],'guardian_id'=>$guardian->id,'revision'=>$report['payload']['revision'],'meaning'=>'Staff-confirmed manual sharing, not delivery/read status.']);return ['message'=>'Report sharing confirmed for this guardian.'];});}
}
